import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem89 preserva operacao e limita afirmacoes a versao e identidade',()=>{for(const [id,titulo] of [['kNmf4r3kzbgWX6Fz3Y0x','Chuveiro Lorenzetti Bella Ducha 4T Ultra para Parede'],['KtvIJ0CLFVYesONQSS8I','Tênis Nike Court Vision Low Masculino'],['kyK4G9Uov6eBaFnNVED7',"Perfume Feminino L' Eau de Parfum Fragrância Floral Gourmand Inebriante com Notas de Íris Nobre, Baunilha e Pralinê La Vie Est Belle Lancôme, Frasco com 100ml"]]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/bivolt|cristal|alta projeção|catálogo confirmado|economia garantida/i);if(id==='kNmf4r3kzbgWX6Fz3Y0x')assert.match(x.comentario,/220 V/);if(id==='kyK4G9Uov6eBaFnNVED7')assert.match(x.comentario,/não comprova/);}});
